from collections import deque

def max_depths(n: int, edges: list, k: int) -> int:
    # Build the tree
    tree = [[] for _ in range(n + 1)]
    for u, v in edges:
        tree[u].append(v)
        tree[v].append(u)

    # DFS to compute dp
    def dfs(u: int, depth: int, level: int) -> int:
        children = []
        for v in tree[u]:
            depth = dfs(v, depth + 1, level)
            if depth >= level:
                children.append(depth)
        if len(children) >= k:
            max_depth = max(children)
            return max_depth + (k - len(children)) * (depth - level)
        else:
            max_depth = 0
            for child in children:
                max_depth = max(max_depth, max_depths(n, edges, k))
            return max_depth + (k - len(children)) * (depth - level)

    return dfs(1, 0, 1)

