from typing import List

def dfs(start: tuple, n: int, m: int, graph: List[List[int]], obstacle_positions: List[tuple],
        modulo: int) -> int:
    stack = [start]

    while stack:
        x, y = stack.pop()

        if (x, y) in obstacle_positions:
            pass  # Skip if obstacle here
        elif (x, y) == (n, m):
            return 1  # Goal reached
        elif (x, y) in graph:
            for neighbour in graph[(x, y)]:
                if neighbour not in obstacle_positions:
                    stack.append((neighbour, (x, y)[::-1]))
    return 0  # No way to reach goal


def find_graph(n: int, m: int, obstacles: List[tuple]) -> List[List[int]]:
    obstacle_positions = set()
    graph = defaultdict(set)
    stack = [((1, 1), ())]

    while stack:
        x, y = stack.pop()

        if (x, y) in obstacle_positions:
            pass  # Skip if obstacle here
        elif (x, y) == (n, m):
            continue  # Goal reached, skip others

        if n == y:
            for _ in range(obstacles.count((x, 1, x, y))):
                for _ in range(obstacles.count((x, y, x, m)) // 2):
                    obstacle_positions.add((x, 1, x, y))
                    obstacle_positions.add((x, y, x, m))

        elif n > y:
            added = barriers[obstacles[y].count((x, y))]  # do same tricks on (x, m) coordinate
            added = max(0, added - (y - y0) // 2)
            obstacle_positions.add((x, y, x, y))
            obstacle_positions.add((x, y, x, y + added))
            obstacle_positions.add((x, y - added // 2, x, y))

        graph[x, y].add((x + 1, y + y0))

        for new_y in (y0, y):
            x0 = obstacles[new_y].count((x, y))[0]  # barriers related to current square (x, y)
            barriers[new_y] = 1 + max(0, sum(barriers[x0 + 1:]) + x0 // 2)
            for _ in range(obstacles[new_y].count((x, new_y))):
                for _ in range(obstacles.count((x, new_y, x, m))):
                    obstacle_positions.add((x, new_y, x, y + 1 + barriers[new_y]))

        stack.extend([(x + 1, y), (x, y + y0)])


    return graph


