        if surface_area < min_surface_area:
            min_surface_area = surface_area
            edges = (x for (j, x), _ in sorted(product(list(prime_factors), repeat=2), key=lambda t: primed[find_prime(t[0]) - 1] + prime_factors[t[1]]))
        if surface_area == V:
            break

    return min_surface_area, tuple(edges)

def product(*args):
    result = 1
    for arg in args:
        result *= arg
    return result

def combinations(iterable, r):
    pool = tuple(iterable)
    n = len(pool)
    if r > n:
        return
    indices = list(range(r))
    yield tuple(pool[i] for i in indices)

# Custom sorting function to sort based on the prime factorization order
