class Solution:
    def findSolution(self, bags, total):
        self.bags = list(bags)
        self.total = total
        if self.total == 0:
            return []
        self.memo = dict()
        self.dp = []
        for i in range(3, self.total - 1):
            self.recursive_bags(i)
            self.dp.append(self.bags)
        return self.dp

    def recursive_bags(self, i):
        if i == self.total:
            self.bags.append([])
            return
        self.dp.clear()
        self.bags.append([
            0,
            i,
            self.num_bags,
            self.num_contents,
        ])
        for bag in self.bags[len(self.bags) - 1]:
            next_i = self.get_next(i, bag)
            if next_i > 0:
                self.recursive_bags(next_i)
            else:
                self.bags[len(self.bags) - 1][0] += 1
        if i == 0:
            self.bags.append([])

    def get_next(self, prev_i, bag_0):
        if prev_i == 0:
            return ((prev_i - bag_0) // 2) + 1
        return (self.total - prev_i - self.dp[len(self.bags) - self.bag_0].num_contents) // 2 + 1

