def find_min_surface_area(V: int) -> Tuple[int, int, int]:
    # Initialize variables
    surface_area = float('inf')
    edge_lengths = [1, 1, 1]

    # Function to create factors of V
    def factors_product(factors: List[Tuple[int, int]]) -> int:
        return reduce(lambda x, y: x * y, (x for (_, x) in factors), 1)

    # Function to update min surface area and corresponding edge lengths
    def update_min_s(a, b, c):
        nonlocal surface_area, edge_lengths
        area = 2 * (a * b + b * c + c * a)
        if area < surface_area or (area == surface_area and any(x != y for (x, y) in zip(edge_lengths, (a, b, c)))):
            surface_area = area
            edge_lengths = [a, b, c]

    # Check for "1" factor which occurs V times
    if V == 1:
        return (1, 1, 1, 1)

    # Check if 2 is a factor of V
    if factors_product([(2, 1)]) % V == 0:
        if V % 2 == 0:
            update_min_s(2, 1, factors_product([(2, 1), (2, 1)/2]) + factors_product([(2, 1), (2, 1)/2], 1))
        else:
            update_min_s(max(1, V//2 + (1 if V % 2 == 1 else 0)), min(ceil(V/2), 2), 2)

    # Check for larger primes up to sqrt(V)
    from math import ceil
    for p in range(3, int(ceil(sqrt(V)))):  # upper limit ceil(sqrt(V))
        if V % p == 0:
            if factors_product([(p, 1)]) % V == 0:
                update_min_s(p, factors_product([(p, 1), (2, p-1)]) + factors_product([(p, 1), (2, p-1)], 1))
                if divisors[p - 1] % p == 0:
                    update_min_s(int(p**divisors[p - 1]), p*p)
                update_min_s(factors_product([(p, 1), divisors[p - 1], p**(divisors[p - 1] + 1) / p]) + factors_product([(p, 1), divisors[p - 1], p**(divisors[p - 1] + 1) / p], 1))
            divisors[p - 1] += 1
            if divisors[p - 1] <= V:
                update_min_s(p, factors_product([(p, 1), (2, p-1)]) + factors_product([(p, 1), (2, p-1)], 1))
                if divisors[p - 1] % p == 0:
                    update_min_s(int(p**divisors[p - 1]), p*p)
                update_min_s(factors_product([(p, 1), divisors[p - 1], p**(divisors[p - 1] + 1) / p]) + factors_product([(p, 1), divisors[p - 1], p**(divisors[p - 1] + 1) / p], 1))

    # Check if 4 is a factor of V
    if factors_product([(2, 2)]) % V == 0:
        update_min_s(2*2, 2, 2)

    return surface_area, *edge_lengths

