from typing import List

def gcd(a: int, b: int) -> int:
    return a if b == 0 else gcd(b, a % b)

def lcm(a: int, b: int) -> int:
    return a * b // gcd(a, b)

def single_multiset(m: List[int], v: int) -> None:
    if (v not in m):
        m[v] = 1
    else:
        m[v] += 1

def set_multiset(m: List[int], index: List[int]) -> None:
    for x in index[1::2]:
        for y in index[2::2]:
            new_multiset = m[index[1]]
            for z in set(m[y] + m[z]):
                single_multiset(new_multiset, z)
            m[index[0]] = new_multiset

def set_multiset_product(m: List[int], index: Tuple[int, Tuple[int, int]]) -> None:
    # Set current multiset's size to gcd of the sizes of two multisets
    for x in (index[1][0], index[2][0]):
        if (x != index[0][0]):
            m[x] = gcd(m[x], m[index[0][0]])
    # Create a new multiset from two multisets if their size converges to n for some index[n]
    for x in (index[1][0], index[2][0]):
        if (m[x] == m[index[0][0]]):
            m[index[0][0]] += m[x]
            del m[x]

def consume_element(multiset: Set[int], index: int) -> int:
    # Return the most frequent element of the multiset.
    element_counts = [0] * 7001
    for x in multiset:
        tmp = x
        while (tmp != index):
            tmp = gcd(tmp, index)
            element_counts[tmp] += 1
    cnt = 0
    for x in element_counts:
        if (x > 0):
            for _ in range(x):
                cnt += 1
    return cnt if cnt % 2 == 0 else cnt

def solve(n: int, q: int) -> List[int]:
    multisets = [[] for _ in range(n)]
    for _ in range(q):
        t, x1, *t2, x2, *t3, x3, *t4, v = map(int, input().split())
