def bfs(graph, start):
    queue = [start]
    visited = [False] * len(graph)
    visited[start] = True
    while queue:
        current = queue.pop(0)
        for neighbor in graph[current]:
            if not visited[neighbor]:
                visited[neighbor] = True
                queue.append(neighbor)
    return visited

def hamiltonian_path(graph, s, t):
    # Perform BFS from s to find an augmenting path to t
    path = []
    visited = bfs(graph, s)
    while t not in visited:
        for node in range(len(visited)):
            if visited[node] and graph[s][node] and not visited[node]:
                path.append(node)
                s = node
                visited[node] = True
    # Construct the path and reverse it to get the transversal
