def solve(num_glades, num_trails, trails):
    graph = [[] for _ in range(num_glades + 1)]
    visited = [False] * (num_glades + 1)
    cycle = 0
    for trail_a, trail_b in trails:
        graph[trail_a].append(trail_b)
        graph[trail_b].append(trail_a)

    def dfs(node):
        visited[node] = True
        for neighbor in graph[node]:
            if not visited[neighbor]:
                cycle = True
                dfs(neighbor)
            elif cycle:
                return node

    for node in range(1, num_glades + 1):
        if not visited[node]:
            dfs(node)

