def rotate(s, n):
    return s[n:] + s[:n]

def count_cyclical_isomorphic_substrings(s, queries):
    n = len(s)
    prev = {query: n for query in queries}
    suffixes = [s[(n-i)+1:] + s[:i] for i in range(n)]
    for i in range(n-1, -1, -1):
        for j in range(n-1, i-1, -1):
            if suffixes[j] == rotate(suffixes[j], i) and suffixes[j].replace(' ','') in prev:
                previous = prev[suffixes[j].replace(' ','')][find_max_index(s, prefix=suffixes[j])]
                count = find_max_index(s, prefix=rotate(s, previous))
                if i == 0 and previous != 0:
                    count += 1
                prev[suffixes[j]] = previous
                n = min(n, i + count)
                yield count
    for query in queries:
        yield n

def find_max_index(s, prefix):
    return len(srstrip(s, prefix, reverse=True).rstrip())

def srstrip(s, prefix, reverse=False):
    for i in range(len(s)-len(prefix), -1, -1):
        if s[i:i+len(prefix)] == prefix and (not reverse or (not s[i:])):
            return s[i-len(prefix)+1:]

