from collections import defaultdict

def find_parent(parent, node):
    if parent[node] == node:
        return node
    return find_parent(parent, parent[node])

def union(parent, rank, x, y):
    rootX = find_parent(parent, x)
    rootY = find_parent(parent, y)
    if rootX != rootY:
        if rank[rootX] < rank[rootY]:
            parent[rootX] = rootY
        elif rank[rootX] > rank[rootY]:
            parent[rootY] = rootX
        else:
            parent[rootY] = rootX
            rank[rootX] += 1

def swap_permutation(permutation, i, j):
    permutation[i], permutation[j] = permutation[j], permutation[i]

def query_solution(permutation, queries):
    parent = defaultdict(int)
    rank = defaultdict(int)
    for i in range(len(permutation)):
        parent[i] = i
    for value in range(len(permutation)):
        for i in range(len(permutation)):
            if (value in permutation[i] and i not in permutation[value]):
                union(parent, rank, value, i)
    result = []
    for query in queries:
        type = query[0]
        if type == 1:
            i, j = query[1], query[2]
            swap_permutation(permutation, i, j)
        elif type == 2:
            path_mex = []
            visit = [False] * len(permutation)
            for i in sorted(permutation):
                if visit[i] == False:
                    order = [i]
                    predecessor = None
                    while predecessor != find_parent(parent, i):
                        predecessor = find_parent(parent, i)
                        order.append(predecessor)
                    visit[i] = True
                    for v in order:
                        if visit[v] == False:
                            path_mex.append(v)
            path_mex = sorted(path_mex)
            if len(path_mex) > 0:
                result.append(len(set(path_mex)) - 1)
            else:
                result.append(0)
    return result

