class ParquetConfigurator:
    def __init__(self, board):
        self.board = board
        self.moved_tiles = 0
        self.total_tiles = 0
        self.current_config = self.board

    def rotate_half_tile(self, row, col):
        # Flip the current tile left
        self.board[(2 * row) + ((col + 1) % 2), (2 * col) + (col // 2)] = 'R'
        self.board[(2 * row) + ((col + 1) % 2), (2 * col) + (col // 2) + 1] = 'L'
        self.board[(2 * row) + (col // 2), (2 * col) + (col // 2) + 1] = 'U'
        self.board[(2 * row) + (col // 2), (2 * col) + (col // 2)] = 'D'

    def transform_board_to_target(self, target_config):
        transformation = 0
        for i in range(2):
            for j in range(3):
                if self.board[i * 2][j * 3 + 1] != 'D':
                    self.board[i * 2][j * 3 + 1] = 'D'
                    self.board[i * 2][j * 3] = 'U'
                    self.board[i * 2][j * 3 + 2] = 'R'
                elif self.board[i * 2][j * 3] != 'R':
                    self.board[i * 2][j * 3] = 'U'
                    self.board[i * 2][j * 3 + 1] = 'D'
                    self.board[i * 2][j * 3 + 2] = 'L'
                elif self.board[i * 2][j * 3 + 2] != 'L':
                    self.board[i * 2][j * 3 + 2] = 'L'
                    self.board[i * 2][j * 3 + 1] = 'R'
                    self.board[i * 2][j * 3] = 'U '
                else:
                    self.board[i * 2][j * 3 + 2] = 'D'
                    self.board[i * 2][j * 3 + 1] = 'U'
                    self.board[i * 2][j * 3] = 'R'

    def find_first_neighboring_half_tile(self):
        x, y = 1, 1
        while x < 2 * len(self.board[0]) + 2 or y < 2 * len(self.board) + 2:
            if not (y in range(2 * len(self.board) + 2) and x in range(2 * len(self.board[0]) + 2) and
                    self.board[y // 2][x // 2] in ['L', 'D', 'U', 'R']):
                if x < len(self.board[0]):
                    return x + 1
                elif y < len(self.board) + 2:
                    return y + 2
                else:
                    return -1

    def get_next_description(self):
        neighbor_x, neighbor_y = self.find_first_neighboring_half_tile()
        self.rotate_half_tile(neighbor_y // 2, neighbor_x // 2)
        self.transform_board_to_target(self.board[neighbor_y // 2][neighbor_x // 2 - 1], neighbor_x // 2, neighbor_y // 2)
        self.transform_board_to_target(self.board[neighbor_y // 2 - 1][neighbor_x // 2 - 1], neighbor_x // 2, neighbor_y // 2)
        return [neighbor_x // 2, neighbor_y // 2], neighbor_x // 2, neighbor_y // 2

    def action(self, step):
        self.total_tiles += 1
        self.moved_tiles += 1
        if self.moved_tiles == self.total_tiles:
            return False
        description = self.get_next_description()
        return description[0] != -1 and self.find_first_neighboring_half_tile() != -1

