from collections import defaultdict, Counter

class Node:
    def __init__(self, val):
        self.val = val
        self.children = []

def build_tree(edges):
    tree = defaultdict(Node)
    for a, b in edges:
        tree[a].children.append(b)
        tree[b].children.append(a)
    return tree

def get_degrees(tree):
    degrees = defaultdict(int)
    for node in tree.values():
        for child in node.children:
            degrees[child] += 1
    return degrees

def is_isomorphic(node1, node2):
    if node1 == None or node2 == None:
        return node1 == node2
    if node1.val != node2.val:
        return False
    if len(node1.children) != len(node2.children):
        return False
    connections = {}
    for child1, child2 in zip(node1.children, node2.children):
        if child1 not in connections:
            if not is_isomorphic(child1, child2):
                return False
            connections[child1] = child2
        elif connections[child1] != child2:
            return False
    return True

def count_isomorphic_subtrees(s, t, mod=10**9 + 7):
    s_tree = build_tree(s)
    t_nodes = Counter(connections(t_node) for _, t_node in t.items())
    count = 0
    for root in t_nodes.keys():
        degrees = get_degrees(s_tree[root])
        if (degrees[root] == t_nodes[root] and
            (t_nodes[root] >= 1 or degrees[root - 1] >= -t_nodes[root + 1])):
            count += 1
    return count

# Read input
num_s_nodes = int(input())
s_edges = [tuple(map(int, input().split())) for _ in range(num_s_nodes-1)]
trees_edges = []
for _ in range(int(input())):
    t_edges = [tuple(map(int, input().split())) for _ in range(int(input())-1)]
    trees_edges.append(tuple(t_edges))
# Output result
num_t_nodes = len(trees_edges)
for _ in range(1000*(1000//num_s_nodes + 1)):
    t_counts = []
    for trees in trees_edges:
        t_node_connections = Counter(connections(t_node) for _, t_node in trees.items())
        t_counts.append(t_node_connections)
    t_count = sum(counter.values() for counter in t_counts)
    num_isomorphic_subtrees = count_isomorphic_subtrees(s_edges, t_count)
    num_isomorphic_subtrees %= mod
    if num_isomorphic_subtrees == 0:
        break
    print(num_isomorphic_subtrees)
