def preprocess_string(s, k):
    result = 0
    i = 0
    end_of_queue = 0

    while i < len(s):
        end_of_queue += k
        if end_of_queue >= len(s):
            end_of_queue = len(s)

        queue = deque()
        current = set()

        while i < end_of_queue and len(queue) < k:
            queue.append(s[i])
            current.add(s[i])
            i += 1

        while len(queue) <= k:
            if s[i] in current and s[i] in queue:
                current.add(s[i])
                i += 1
                queue.popleft()
            else:
                break

        while i < end_of_queue and len(queue) >= k:
            result += 1
            queue.popleft()

    return result

def process_queries(s, queries):
    result = []
    for query in queries:
        result.append(preprocess_string(s, len(query) - 1))
    return result

